function startProject (parentElement, baseURI, flashVars, attributes, callback) {
	createStage({
		parent: parentElement,
		base: baseURI,
		autoSize: 300,
		panel: {
			align: 'right',
			buttons: ["displayState","sound"]
		},
		stats: {
			align: 'left'
		},
		mobile: {
			orientation: 'auto',
			maximize: true
		}
	}, flashVars, attributes, callback);
}

